// Define a representative geometry for Southern Ethiopia.
// This is an approximate polygon covering parts of Somali, Oromia, and SNNP regions.
var southernEthiopia = ee.Geometry.Polygon([[
  [37.00, 3.50],
  [43.00, 3.50],
  [43.00, 7.00],
  [37.00, 7.00],
  [37.00, 3.50]
]]);

// Center the map on the area of interest.
Map.centerObject(southernEthiopia, 6);

// --- Period of Interest: October-November 2021 ---

// Define the start and end dates for the period of interest.
var startDate_2021 = ee.Date('2021-10-01');
var endDate_2021 = ee.Date('2021-11-30');

// Load the CHIRPS Daily precipitation dataset.
var chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

// Filter the dataset for the 2021 period and the region.
var rainfall_2021 = chirps
    .filterDate(startDate_2021, endDate_2021)
    .filterBounds(southernEthiopia);

// Calculate the total rainfall for the 2021 period.
var totalRainfall_2021 = rainfall_2021.sum();

// Calculate the mean total rainfall within the Southern Ethiopia region for 2021.
var meanRainfall_2021 = totalRainfall_2021.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: southernEthiopia,
  scale: 5566, // CHIRPS resolution in meters
  maxPixels: 1e9
});

print('Total Rainfall (Oct-Nov 2021) in mm:', meanRainfall_2021.get('precipitation'));

// --- Baseline Period: October-November from 2000-2013 ---

// Define the baseline years.
var startYear = 2000;
var endYear = 2013;
var years = ee.List.sequence(startYear, endYear);

// Function to calculate total rainfall for Oct-Nov for a given year.
var yearlyRainfall = function(year) {
  var startDate = ee.Date.fromYMD(year, 10, 1);
  var endDate = ee.Date.fromYMD(year, 11, 30);
  var total = chirps
      .filterDate(startDate, endDate)
      .filterBounds(southernEthiopia)
      .sum();
  return total;
};

// Map the function over the baseline years to get a collection of total rainfall images.
var yearlyTotals = ee.ImageCollection.fromImages(
  years.map(yearlyRainfall)
);

// Calculate the mean of the yearly total rainfall images.
var longTermAverage = yearlyTotals.mean();

// Calculate the mean long-term average rainfall within the Southern Ethiopia region.
var meanLongTermAverage = longTermAverage.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: southernEthiopia,
  scale: 5566,
  maxPixels: 1e9
});

print('Long-Term Average Rainfall (Oct-Nov, 2000-2013) in mm:', meanLongTermAverage.get('precipitation'));

// --- Visualization ---

// Define visualization parameters for rainfall.
var precipVis = {
  min: 0,
  max: 200,
  palette: ['white', 'blue']
};

// Add layers to the map.
Map.addLayer(longTermAverage.clip(southernEthiopia), precipVis, 'Long-Term Average (2000-2013)');
Map.addLayer(totalRainfall_2021.clip(southernEthiopia), precipVis, 'Total Rainfall (2021)');
Map.addLayer(southernEthiopia, {color: 'FF0000'}, 'Southern Ethiopia AOI', false);

// Define representative geometries for Southern and Northern Ethiopia.
var southernEthiopia = ee.Geometry.Polygon([[
  [37.00, 3.50], [43.00, 3.50], [43.00, 7.00], [37.00, 7.00], [37.00, 3.50]
]]);
var northernEthiopia = ee.Geometry.Polygon([[
  [36.50, 9.50], [40.00, 9.50], [40.00, 14.50], [36.50, 14.50], [36.50, 9.50]
]]);

// Center the map to view both regions and add them as layers.
Map.centerObject(ee.Geometry.Point(39, 9), 5);
Map.addLayer(southernEthiopia, {color: 'FF0000'}, 'Southern Ethiopia AOI');
Map.addLayer(northernEthiopia, {color: '0000FF'}, 'Northern Ethiopia AOI');

// Load the CHIRPS Daily precipitation dataset.
var chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

// --- Define Time Periods ---
var anomalyStartDate = '2021-10-01';
var anomalyEndDate = '2021-11-30';
var baselineStartYear = 2000;
var baselineEndYear = 2013;

// --- Function to Calculate and Print Rainfall Anomaly ---
var calculateRainfallAnomaly = function(region, regionName) {
  // 1. Calculate Total Rainfall for Oct-Nov 2021
  var rainfall2021 = chirps
      .filter(ee.Filter.date(anomalyStartDate, anomalyEndDate))
      .sum();

  var meanRainfall2021 = rainfall2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000, // Scale in meters for the reducer
    maxPixels: 1e9
  }).get('precipitation');

  // 2. Calculate Long-Term Average for Oct-Nov (2000-2013)
  var baselineYears = ee.List.sequence(baselineStartYear, baselineEndYear);

  var yearlyTotals = ee.ImageCollection.fromImages(
    baselineYears.map(function(year) {
      var startDate = ee.Date.fromYMD(year, 10, 1);
      var endDate = ee.Date.fromYMD(year, 11, 30);
      return chirps
          .filter(ee.Filter.date(startDate, endDate))
          .sum()
          .set('year', year);
    })
  );

  var longTermAverage = yearlyTotals.mean();

  var meanLongTermAverage = longTermAverage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // 3. Calculate the Anomaly (2021 rainfall - long-term average)
  var anomaly = ee.Number(meanRainfall2021).subtract(ee.Number(meanLongTermAverage));
  var anomalyPercentage = anomaly.divide(ee.Number(meanLongTermAverage)).multiply(100);


  // Print the results for the region
  print('--- Results for ' + regionName + ' ---');
  print('Total Rainfall (Oct-Nov 2021) in mm:', meanRainfall2021);
  print('Long-Term Average (2000-2013) in mm:', meanLongTermAverage);
  print('Rainfall Anomaly (2021 vs Average) in mm:', anomaly);
  print('Rainfall Anomaly as % of Average:', anomalyPercentage);
};

// Run the function for both regions
calculateRainfallAnomaly(southernEthiopia, 'Southern Ethiopia');
calculateRainfallAnomaly(northernEthiopia, 'Northern Ethiopia');

// Define the Area of Interest (AOI) for Shanghai and Beijing
var shanghai = ee.Geometry.Point([121.4737, 31.2304]);
var beijing = ee.Geometry.Point([116.4074, 39.9042]);

// Define the date range for the anomaly period
var anomalyStartDate = '2013-08-05';
var anomalyEndDate = '2013-08-12';

// Define the baseline period for the long-term average
var baselineStartYear = 2000;
var baselineEndYear = 2012;

// Load the MODIS Land Surface Temperature (LST) dataset
var modisLST = ee.ImageCollection('MODIS/061/MOD11A1');

// --- Calculations for Shanghai ---

// Calculate the long-term average LST for the baseline period in Shanghai
var baselineShanghai = ee.ImageCollection(
  ee.List.sequence(baselineStartYear, baselineEndYear).map(function(year) {
    var startDate = ee.Date.fromYMD(year, 8, 5);
    var endDate = ee.Date.fromYMD(year, 8, 12);
    return modisLST.filter(ee.Filter.date(startDate, endDate))
                   .select('LST_Day_1km')
                   .mean()
                   .multiply(0.02) // Apply scale factor to get Kelvin
                   .subtract(273.15); // Convert to Celsius
  })
).mean();

// Calculate the average LST for the anomaly period in 2013 in Shanghai
var anomalyShanghai = modisLST.filter(ee.Filter.date(anomalyStartDate, anomalyEndDate))
                              .select('LST_Day_1km')
                              .mean()
                              .multiply(0.02) // Apply scale factor
                              .subtract(273.15); // Convert to Celsius

// Calculate the LST anomaly for Shanghai
var lstAnomalyShanghai = anomalyShanghai.subtract(baselineShanghai);

// --- Calculations for Beijing ---

// Calculate the long-term average LST for the baseline period in Beijing
var baselineBeijing = ee.ImageCollection(
  ee.List.sequence(baselineStartYear, baselineEndYear).map(function(year) {
    var startDate = ee.Date.fromYMD(year, 8, 5);
    var endDate = ee.Date.fromYMD(year, 8, 12);
    return modisLST.filter(ee.Filter.date(startDate, endDate))
                   .select('LST_Day_1km')
                   .mean()
                   .multiply(0.02) // Apply scale factor
                   .subtract(273.15); // Convert to Celsius
  })
).mean();

// Calculate the average LST for the anomaly period in 2013 in Beijing
var anomalyBeijing = modisLST.filter(ee.Filter.date(anomalyStartDate, anomalyEndDate))
                            .select('LST_Day_1km')
                            .mean()
                            .multiply(0.02) // Apply scale factor
                            .subtract(273.15); // Convert to Celsius

// Calculate the LST anomaly for Beijing
var lstAnomalyBeijing = anomalyBeijing.subtract(baselineBeijing);

// --- Print the results ---

// Use reduceRegion to get the numerical anomaly values for the points of interest
var anomalyValueShanghai = lstAnomalyShanghai.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: shanghai,
  scale: 1000
}).get('LST_Day_1km');

var anomalyValueBeijing = lstAnomalyBeijing.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: beijing,
  scale: 1000
}).get('LST_Day_1km');

print('Shanghai Land Surface Temperature Anomaly (Celsius):', anomalyValueShanghai);
print('Beijing Land Surface Temperature Anomaly (Celsius):', anomalyValueBeijing);

/**
 * Function to mask clouds using the Sentinel-2 QA band
 * @param {ee.Image} image Sentinel-2 image
 * @return {ee.Image} cloud masked Sentinel-2 image
 */
function maskS2clouds(image) {
  var qa = image.select('QA60');

  // Bits 10 and 11 are clouds and cirrus, respectively.
  var cloudBitMask = 1 << 10;
  var cirrusBitMask = 1 << 11;

  // Both flags should be set to zero, indicating clear conditions.
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

  return image.updateMask(mask).divide(10000);
}

var visualization = {
  min: 0.0,
  max: 0.3,
  bands: ['B4', 'B3', 'B2'],
};

Map.setCenter(-111.760162, 50.710872, 10);


var dataset = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                  .filterDate('2025-08-25', '2025-08-26')
                  // Pre-filter to get less cloudy granules.
                  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE',20))
                  .map(maskS2clouds);
Map.addLayer(dataset.mean(), visualization, 'after');

var dataset_b = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                  .filterDate('2025-08-14', '2025-08-22')
                  // Pre-filter to get less cloudy granules.
                  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE',20))
                  .map(maskS2clouds);
Map.addLayer(dataset_b.mean(), visualization, 'before');

// =======================
// Bear Island (Bjørnøya) reference
// =======================
var bearIsland = ee.Geometry.Point([19.017, 74.517]); // lon, lat

// Offset ~km south using degrees (≈111.32 km per degree latitude)
function southPoint(origin, kmSouth) {
  var dLat = ee.Number(kmSouth).divide(111.32);
  var lat = ee.Number(origin.coordinates().get(1)).subtract(dLat);
  var lon = ee.Number(origin.coordinates().get(0));
  return ee.Geometry.Point([lon, lat]);
}
var pt100 = southPoint(bearIsland, 100);
var pt250 = southPoint(bearIsland, 250);

// 10 km radius buffers for stats/visual clarity
var bufKm = 10;
var area100 = pt100.buffer(bufKm * 1000);
var area250 = pt250.buffer(bufKm * 1000);

// =======================
// Date: 2025-08-05 (±1 day, median composite)
// =======================
var start = ee.Date('2025-08-04');
var end   = ee.Date('2025-08-06');

// =======================
// MODIS Aqua surface reflectance (C61)
// Dataset: MODIS/061/MYD09GA (Aqua)
// Bands used: b03 (~469 nm, "blue"), b04 (~555 nm, "green")
// =======================
var coll = ee.ImageCollection('MODIS/061/MYD09GA')
  .filterDate(start, end)
  .filterBounds(bearIsland)
  .select(['sur_refl_b03','sur_refl_b04','state_1km']);

// --- QA cloud mask (state_1km bits) ---
// Bits 0-1: Cloud state (0=clear, 1=cloudy, 2=mixed, 3=not set)
// Bit 10: Cirrus detected
function maskClouds(img) {
  var qa = img.select('state_1km').toInt16();

  // Bits 0–1: cloud state (0=clear, 1=cloudy, 2=mixed, 3=not set)
  var cloudState = qa.bitwiseAnd(3);         // no shift needed for bits 0–1
  var isCloudy   = cloudState.neq(0);

  // Example extra mask: single-bit flag (shift then AND 1)
  var cirrus = qa.rightShift(10).bitwiseAnd(1).eq(1);

  var clear = isCloudy.not().and(cirrus.not());
  return img.updateMask(clear);
}

var sr = coll.map(maskClouds)
             .median()
             .select(['sur_refl_b03','sur_refl_b04'])
             .rename(['B03','B04'])
             .multiply(0.0001);  // scale factor per MYD09 docs

// =======================
// OC3-style chlorophyll-a proxy
// Classic OC3M: X = log10(max(Rrs443,Rrs488)/Rrs551) then 10^(a0+a1X+...)
// Here we approximate with surface reflectance ratio B03(∼469)/B04(∼555).
// Coeffs (NASA OC3M v6): a0=0.283, a1=-2.753, a2=1.457, a3=0.659, a4=-1.403
// =======================
var eps = 1e-6;
var ratio = sr.select('B03').add(eps).divide(sr.select('B04').add(eps));
var X = ratio.log10();
var a0 = 0.283, a1 = -2.753, a2 = 1.457, a3 = 0.659, a4 = -1.403;
var poly = ee.Image.constant(a0)
  .add(X.multiply(a1))
  .add(X.pow(2).multiply(a2))
  .add(X.pow(3).multiply(a3))
  .add(X.pow(4).multiply(a4));

// chlor_a in mg m^-3 (proxy)
var chlorA = ee.Image(10).pow(poly).rename('chlor_a_proxy');

// Optional sanity mask: keep reasonable ocean values
var chlorMask = chlorA.gt(0.02).and(chlorA.lt(50)); // 0.02–50 mg/m^3
chlorA = chlorA.updateMask(chlorMask);

// =======================
// Visualization (water-color palette)
// =======================
var chlVis = {
  min: 0.05,
  max: 15.0,
  palette: [
    '001146','00336e','005a8c','1e86b6','4bb3d1',
    '7ad3d4','a7e3c3','d4f0a1','f6f28f','f9cc74','f29c53','e35a3f','c22e3a'
  ]
};

// Map extent & layers
var bbox = area100.union(area250).buffer(30000);
Map.centerObject(bbox, 6);
Map.addLayer(chlorA.clip(bbox), chlVis, 'Chlorophyll-a (OC3 proxy) • Aqua MYD09GA • 2025-08-05', true);
Map.addLayer(area100, {color: 'cyan'},   '100 km S • 10 km buffer');
Map.addLayer(area250, {color: 'magenta'},'250 km S • 10 km buffer');
Map.addLayer(bearIsland, {color: 'yellow'}, 'Bear Island ref', false);

// =======================
// Statistics
// =======================
function meanChl(img, region, label){
  var stats = img.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.stdDev(), sharedInputs: true}),
    geometry: region,
    scale: 1000,    // MYD09GA resolution
    maxPixels: 1e12,
    bestEffort: true
  });
  print(label + ' mean chlor-a proxy (mg/m^3):', stats.get('chlor_a_proxy_mean'));
  print(label + ' stdDev chlor-a proxy (mg/m^3):', stats.get('chlor_a_proxy_stdDev'));
  return stats;
}

var s100 = meanChl(chlorA, area100, '100 km south');
var s250 = meanChl(chlorA, area250, '250 km south');

// Difference summary
var mean100 = ee.Number(s100.get('chlor_a_proxy_mean'));
var mean250 = ee.Number(s250.get('chlor_a_proxy_mean'));
var diff = mean250.subtract(mean100);
var pct  = diff.divide(mean100).multiply(100);
print('Δ chlor-a proxy (250 − 100) mg/m^3:', diff);
print('Percent difference (%):', pct);

// For quick QC:
print('Ratio (B03/B04) stats at 100 km S:', chlorA.addBands(ratio.rename('ratio')).reduceRegion({
  reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.minMax(), sharedInputs: true}),
  geometry: area100, scale: 1000, maxPixels: 1e12, bestEffort: true
}));

// Wolf Volcano (Galápagos)
var wolfVolcano = ee.Geometry.Point([-91.33, 0.05]);

// Time range: January 1–7, 2022
var startDate = '2022-01-01';
var endDate = '2022-01-08';  // end date exclusive, so include Jan 7

// Load VIIRS Day/Night Band dataset
var dataset = ee.ImageCollection('NOAA/VIIRS/001/VNP46A1')
  .filterDate(startDate, endDate)
  .filterBounds(wolfVolcano)
  .select('DNB_At_Sensor_Radiance_500m');

// Visualization parameters
var dnbVis = {
  min: 0,
  max: 10,
  palette: ['black', 'purple', 'cyan', 'green', 'yellow', 'red', 'white'],
};

// Center map over Wolf Volcano
Map.setCenter(-91.33, 0.05, 8);

// Print available dates
var imageList = dataset.toList(dataset.size());
var n = imageList.size();
print('Number of images found:', n);
print('Dates available:', imageList.map(function(img) {
  return ee.Image(img).date().format('YYYY-MM-dd');
}));

// Add each image (each day) to the map
for (var i = 0; i < 7; i++) {
  var img = ee.Image(imageList.get(i));
  var date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd');
  Map.addLayer(img, dnbVis, 'DNB Radiance ' + date.getInfo());
}
